342	          headers,
343	          data: { count: this.retryCount }
344	        })
345	      }
346	
347	      // Let's start with a weak etag check
348	      if (this.etag != null && this.etag !== headers.etag) {
349	        // We always throw here as we want to indicate that we entred unexpected path
