386	
387	        if (range == null || range.end == null) {
388	          this.headersSent = true
389	          this.handler.onResponseStart?.(
390	            this.controllerProxy,
391	            statusCode,
392	            headers,
393	            statusMessage
394	          )
395	          return
396	        }
397	
398	        validatePartialResponseContentLength(headers, range, statusCode, this.retryCount)
399	
400	        const { start, size, end = size ? size - 1 : null } = range
